package org.rabochaya.projects;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.Bundle;import android.provider.OpenableColumns;import android.widget.*;
import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Explicit local SAF import; files and KML references commit together. */
public final class AttachmentsActivity extends Activity {
 private static final int PICK=4401;private long projectId;private String featureId;private LinearLayout root;private TextView status;private boolean busy;private volatile boolean disposed;private Uri queued;
 private final ExecutorService worker=Executors.newSingleThreadExecutor();
 protected void onCreate(Bundle state){super.onCreate(state);projectId=getIntent().getLongExtra("project",-1);featureId=getIntent().getStringExtra("feature");root=new LinearLayout(this);root.setOrientation(1);root.setPadding(12,12,12,12);root.setBackgroundColor(0xff232d1d);setContentView(root);load();}
 private TextView text(String value){TextView t=new TextView(this);t.setText(value);t.setTextColor(0xffffffff);t.setTextSize(16);t.setPadding(10,12,10,12);return t;}
 private void button(LinearLayout parent,String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextColor(0xff202020);b.setBackgroundColor(0xffe8ece3);parent.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->{if(!busy)action.run();});}
 private void load(){busy=true;root.removeAllViews();status=text("Открытие вложений…");root.addView(status);worker.execute(()->{ProjectStore store=null;try{store=new ProjectStore(this);KmlProject p=store.load(projectId);org.w3c.dom.Element f=p.byId(featureId);if(f==null)throw new IOException("Объект удалён");final List<MediaLinks.Item> items=MediaLinks.list(f);final HashMap<String,Integer> sizes=new HashMap<>();for(MediaLinks.Item item:items){byte[] bytes=p.assets.get(MediaLinks.path(p,item.href));sizes.put(item.id,bytes==null?-1:bytes.length);}runOnUiThread(()->{if(disposed)return;busy=false;show(items,sizes);if(queued!=null){Uri uri=queued;queued=null;importFile(uri);}});}catch(final Exception e){runOnUiThread(()->{if(!disposed){busy=false;status.setText("Не удалось открыть вложения: "+e.getMessage());button(root,"Назад",()->finish());}});}finally{if(store!=null)store.close();}});}
 private void show(List<MediaLinks.Item> items,Map<String,Integer> sizes){root.removeAllViews();status=text("Вложений: "+items.size());root.addView(status);button(root,"Добавить фото, аудио или видео",()->pick());button(root,"Назад",()->finish());ScrollView scroll=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));for(MediaLinks.Item item:items){Integer size=sizes.get(item.id);button(list,item.name+" · "+item.mime+" · "+(size==null||size<0?"файл отсутствует":size+" байт"),()->new AlertDialog.Builder(this).setTitle(item.name).setItems(new String[]{"Открыть","Убрать из объекта"},(d,w)->{if(w==0){Intent i=new Intent(this,MediaPlaybackActivity.class);i.putExtra("project",projectId).putExtra("feature",featureId).putExtra("attachment",item.id);startActivity(i);}else new AlertDialog.Builder(this).setMessage("Убрать это вложение из объекта? Общий файл сохранится, если он нужен другому объекту.").setPositiveButton("Убрать",(confirm,which)->remove(item.id)).setNegativeButton("Отмена",null).show();}).setNegativeButton("Отмена",null).show());}}
 private void pick(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/*","audio/*","video/*"});i.putExtra(Intent.EXTRA_LOCAL_ONLY,true);try{startActivityForResult(i,PICK);}catch(ActivityNotFoundException e){status.setText("На устройстве нет системного выбора файлов");}}
 protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request==PICK&&result==RESULT_OK&&intent!=null&&intent.getData()!=null){if(busy)queued=intent.getData();else importFile(intent.getData());}}
 private void importFile(final Uri uri){
  if(!"content".equals(uri.getScheme())&&!"file".equals(uri.getScheme())){status.setText("Выберите локальный файл");return;}
  busy=true;status.setText("Сохранение вложения…");worker.execute(()->{ProjectStore store=null;try{
   String name=uri.getLastPathSegment(),type=getContentResolver().getType(uri);if("content".equals(uri.getScheme()))try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}
   ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Файл недоступен");byte[] buffer=new byte[16384];int n;while((n=in.read(buffer))!=-1){if(disposed)throw new IOException("Импорт отменён");if(out.size()+n>ProjectWrites.MAX_FILE)throw new IOException("Предел одного вложения — 8 МиБ");out.write(buffer,0,n);}}
   if(disposed)throw new IOException("Импорт отменён");store=new ProjectStore(this);KmlProject p=store.load(projectId);org.w3c.dom.Element f=p.byId(featureId);if(f==null)throw new IOException("Объект удалён");MediaLinks.add(p,f,name,type,out.toByteArray());ProjectWrites.save(store,projectId,p);
   runOnUiThread(()->{if(!disposed){busy=false;load();}});
  }catch(final Exception e){runOnUiThread(()->{if(!disposed){busy=false;status.setText("Вложение не добавлено: "+e.getMessage());}});}finally{if(store!=null)store.close();}});
 }
 private void remove(final String id){busy=true;status.setText("Удаление ссылки на вложение…");worker.execute(()->{ProjectStore store=null;try{store=new ProjectStore(this);KmlProject p=store.load(projectId);org.w3c.dom.Element f=p.byId(featureId);if(f==null)throw new IOException("Объект удалён");MediaLinks.remove(p,f,id);ProjectWrites.save(store,projectId,p);runOnUiThread(()->{if(!disposed){busy=false;load();}});}catch(final Exception e){runOnUiThread(()->{if(!disposed){busy=false;status.setText("Не удалось убрать вложение: "+e.getMessage());}});}finally{if(store!=null)store.close();}});}
 protected void onDestroy(){disposed=true;worker.shutdown();super.onDestroy();}
}
